package pl.edu.pjatk.mpr.aggregates;
import org.junit.jupiter.api.Test;import java.time.LocalDate;import java.time.LocalDateTime;import static org.junit.jupiter.api.Assertions.*;
class DayScheduleTest { private final DaySchedule schedule=new DaySchedule("day-1",LocalDate.of(2026,11,14)); @Test void assignsNonConflictingEvents(){schedule.assign("event-1","A",slot(10,11));schedule.assign("event-2","A",slot(11,12));assertEquals(2,schedule.entryCount());} @Test void rejectsOverlappingEventsInSameRoom(){schedule.assign("event-1","A",slot(10,11));assertThrows(DomainRuleViolation.class,()->schedule.assign("event-2","A",slot(10,12)));} @Test void allowsOverlapInDifferentRooms(){schedule.assign("event-1","A",slot(10,11));schedule.assign("event-2","B",slot(10,11));assertEquals(2,schedule.entryCount());} @Test void publishesOnlyNonEmptySchedule(){assertThrows(DomainRuleViolation.class,schedule::publish);schedule.assign("event-1","A",slot(10,11));SchedulePublished event=schedule.publish();assertEquals(1,event.entryCount());assertEquals(DaySchedule.Status.PUBLISHED,schedule.status());} @Test void publishedScheduleIsClosed(){schedule.assign("event-1","A",slot(10,11));schedule.publish();assertThrows(DomainRuleViolation.class,()->schedule.assign("event-2","B",slot(11,12)));} private TimeSlot slot(int start,int end){return new TimeSlot(LocalDateTime.of(2026,11,14,start,0),LocalDateTime.of(2026,11,14,end,0));} }
